package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.mock.web.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.contracts.*;
class FormalInvocationUncertaintyControllerTest {
 FormalInvocationUncertaintyController c;ServiceCertificateIdentity identity;FormalInvocationUncertainty authority;MockHttpServletRequest request;MockHttpServletResponse response;String id="00000000-0000-4000-8000-000000000001";
 @BeforeEach void setup()throws Exception{identity=mock(ServiceCertificateIdentity.class);authority=mock(FormalInvocationUncertainty.class);c=new FormalInvocationUncertaintyController(identity,authority,new FormalInvocationHttpSchema(new FormalInvocationSchema()));request=new MockHttpServletRequest();response=new MockHttpServletResponse();request.addHeader("X-Schema-Version","1.0.0");request.setContent(("{\"schema_version\":\"1.0.0\",\"tenant_id\":\""+id+"\",\"original_actor_id\":\""+id+"\",\"dispatch_attempt_id\":\""+id+"\",\"kind\":\"TRANSPORT_OUTCOME_UNKNOWN\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test void identityMustPrecedeBodyRead()throws Exception{var r=spy(request);doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(identity).require(r);assertThrows(TenantAccessException.class,()->c.record(r,response,id));verify(r,never()).getInputStream();verifyNoInteractions(authority);}
 @Test void unknownReportCannotSupplyUsageOrMoney(){request.setContent(new String(request.getContentAsByteArray(),java.nio.charset.StandardCharsets.UTF_8).replace("\"kind\":","\"settled_amount\":\"0\",\"kind\":").getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(TenantAccessException.class,()->c.record(request,response,id));verifyNoInteractions(authority);}
 @Test void duplicateSchemaHeaderRejected(){request.addHeader("X-Schema-Version","1.0.0");assertThrows(TenantAccessException.class,()->c.record(request,response,id));verifyNoInteractions(authority);}
 @Test void validReportUsesOriginalAttemptAuthority()throws Exception{when(authority.record(request,id,id,id,id)).thenReturn(new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("status","UNKNOWN"));assertEquals("UNKNOWN",c.record(request,response,id).required("data").required("status").textValue());verify(authority).record(request,id,id,id,id);assertEquals("no-store",response.getHeader("Cache-Control"));}
}
